import{_ as a,o,c as t,a2 as e}from"./chunks/framework.A5mep7Fe.js";const d=JSON.parse('{"title":"🧭 01 · 职业生涯规划","description":"","frontmatter":{},"headers":[],"relativePath":"10-职业发展与资源/01-职业生涯规划.md","filePath":"10-职业发展与资源/01-职业生涯规划.md","lastUpdated":1786806808000}'),i={name:"10-职业发展与资源/01-职业生涯规划.md"};function r(n,l,s,h,u,p){return o(),t("div",null,[...l[0]||(l[0]=[e('<h1 id="🧭-01-·-职业生涯规划" tabindex="-1">🧭 01 · 职业生涯规划 <a class="header-anchor" href="#🧭-01-·-职业生涯规划" aria-label="Permalink to &quot;🧭 01 · 职业生涯规划&quot;">​</a></h1><blockquote><p>用「跨周期」视角做职业决策。别问「现在什么最火」，问「五年后什么还重要、我怎么积累它」。</p></blockquote><hr><h2 id="一、方向选择的二维框架" tabindex="-1">一、方向选择的二维框架 <a class="header-anchor" href="#一、方向选择的二维框架" aria-label="Permalink to &quot;一、方向选择的二维框架&quot;">​</a></h2><p><strong>维度1：你的优势</strong></p><ul><li>研究/数学强 → 算法岗（模型/训练/对齐）</li><li>工程/系统强 → 开发/平台/AI 应用开发</li><li>产品/沟通强 → AI 产品/售前/FDE</li><li>跨界（技术+行业）→ 垂直行业 AI（金融/医疗/法务）</li></ul><p><strong>维度2：环境约束</strong></p><ul><li>学历/论文 → 影响算法岗上限（尤其研究型）</li><li>时间/家庭 → 影响能否高强度投入</li><li>城市 → 一线 AI 机会多，但成本高</li></ul><blockquote><p>没有「最好方向」，只有「最适合你约束 + 能积累复利」的方向。</p></blockquote><h2 id="二、能力复利模型" tabindex="-1">二、能力复利模型 <a class="header-anchor" href="#二、能力复利模型" aria-label="Permalink to &quot;二、能力复利模型&quot;">​</a></h2><p>优先积累「十年后还在用」的能力：</p><ul><li>数学与系统底层、软件工程、分布式、优化思维</li><li>对「误差与不确定性」的直觉</li><li>学习新方法的能力（元能力）</li><li>领域 know-how（行业理解）</li></ul><p>这些换任何技术栈都不作废 → 真正的护城河。</p><h2 id="三、3-5-年路径建议" tabindex="-1">三、3-5 年路径建议 <a class="header-anchor" href="#三、3-5-年路径建议" aria-label="Permalink to &quot;三、3-5 年路径建议&quot;">​</a></h2><ul><li><strong>第1年</strong>：打基础、做一个完整项目、拿第一个 offer</li><li><strong>第2-3年</strong>：在岗位上深挖（成为某模块 owner）、建立技术影响力（博客/分享）</li><li><strong>第3-5年</strong>：从「执行」到「决策」（主导设计/带人/选型），积累行业判断力</li></ul><h2 id="四、常见陷阱" tabindex="-1">四、常见陷阱 <a class="header-anchor" href="#四、常见陷阱" aria-label="Permalink to &quot;四、常见陷阱&quot;">​</a></h2><ul><li>频繁跳槽无积累（每段都从零）</li><li>只追热点不筑底（技术一换就慌）</li><li>闭门造车不输出（无影响力、难晋升）</li><li>忽视软实力（沟通/项目管理），卡在中层</li></ul><h2 id="五、高频追问" tabindex="-1">五、高频追问 <a class="header-anchor" href="#五、高频追问" aria-label="Permalink to &quot;五、高频追问&quot;">​</a></h2><p><strong>Q：算法岗和开发岗怎么选？</strong></p><blockquote><p>看优势与约束：研究/数学/学历 → 算法；工程/系统/想快速落地 → 开发/AI 应用开发。AI 应用开发是两者交叉的高性价比路线。</p></blockquote><p><strong>Q：要不要读研/读博？</strong></p><blockquote><p>想做前沿研究/进大厂研究岗/发论文 → 读博有价值；想做工程/应用落地 → 硕士或工作积累更实在。看目标倒推。</p></blockquote><hr><p>➡️ 下一步：<a href="./02-大厂与AI公司指南">02-大厂与AI公司指南</a></p>',24)])])}const _=a(i,[["render",r]]);export{d as __pageData,_ as default};
